package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class AccountSettingsDialog {
 static void show(Context c,boolean password){NativeSheet sheet=new NativeSheet(c,password?"Alterar senha":"Alterar e-mail");EditText old=NativeSheet.input(c,"Senha atual",128),value=NativeSheet.input(c,password?"Nova senha":"Novo e-mail",254),confirm=NativeSheet.input(c,password?"Confirme a nova senha":"Confirme o e-mail",254);if(password){int input=android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD;old.setInputType(input);value.setInputType(input);confirm.setInputType(input);sheet.body.addView(old);}else{value.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);confirm.setInputType(value.getInputType());}sheet.body.addView(value);sheet.body.addView(confirm);TextView state=NativeSheet.text(c,"",13,0xffbea9d7);sheet.body.addView(state);Button save=new Button(c);save.setText("Salvar alteração");AppStyle.button(save,true);sheet.body.addView(save);save.setOnClickListener(v->{String next=value.getText().toString(),check=confirm.getText().toString();if(!next.equals(check)||password&&(next.length()<8||old.getText().toString().isEmpty())||!password&&!android.util.Patterns.EMAIL_ADDRESS.matcher(next).matches()){state.setText(password?"Informe a senha atual e duas senhas novas iguais, com pelo menos 8 caracteres.":"Informe o mesmo e-mail válido nos dois campos.");return;}sheet.busy(true);save.setEnabled(false);new AccountRepository(c).updateAuth(password,next,old.getText().toString(),(rows,error)->{sheet.busy(false);if(error!=null){state.setText(error);return;}old.setText("");value.setText("");confirm.setText("");state.setText(password?"Senha atualizada.":"Pedido enviado. Confirme os links recebidos no endereço atual e no novo, conforme solicitado.");});});sheet.show();}
}
